{
  "interpretation": {
    "name": "TightenWithNR7OnLine1",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring NR7 to station st1 of line 1, tighten the fasteners per the F25 program, evaluate and record the result, then return NR7 to the crib.",
    "constraints": [
      "NR7 must be reserved before any use and released after it is returned to the crib",
      "NR7 must be at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program, with no literal process values in the Recipe",
      "The tightening must be evaluated against its program and recorded for traceability",
      "transport-tool Steps must be delegated to agvexecutor",
      "Every tool-using Step renews the lease with the reservation token and depends on reserve-tool"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-nr7-line1",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "fetch-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "evaluate-and-record",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["fetch-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "evaluate-and-record",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-result",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "fetch-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-result",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7", "transport-to-crib"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
